ALTER TABLE HR2.JOB_HISTORY DISABLE CONSTRAINT JHIST_DEPT_FK;   
ALTER TABLE HR2.DEPARTMENTS DISABLE CONSTRAINT DEPT_LOC_FK;   
DELETE FROM HR2.JOB_HISTORY;   
DELETE FROM HR2.DEPARTMENTS;   
INSERT INTO HR2.DEPARTMENTS (DEPARTMENT_ID, DEPARTMENT_NAME, MANAGER_ID, LOCATION_ID) SELECT DEPARTMENT_ID, DEPARTMENT_NAME, MANAGER_ID, LOCATION_ID FROM HR.DEPARTMENTS WHERE DEPARTMENTS.DEPARTMENT_ $\mathtt { I D } = \mathtt { I 0 }$ ;   
INSERT INTO HR2.JOB_HISTORY (EMPLOYEE_ID, START_DATE, END_DATE, JOB_ID, DEPARTMENT_ID) SELECT EMPLOYEE_ID, START_DATE, END_DATE, JOB_ID, DEPARTMENT_ID FROM HR.JOB_HISTORY WHERE JOB_HISTORY.EMPLOYEE_ID $_ { 1 = 1 2 2 }$ AND JOB_HISTORY.START_DATE $: =$ DATE '1999-01-01';   
ALTER TABLE HR2.DEPARTMENTS ENABLE CONSTRAINT DEPT_LOC_FK;   
ALTER TABLE HR2.JOB_HISTORY ENABLE CONSTRAINT JHIST_DEPT_FK;
